import json
import re
import datetime
from zoneinfo import ZoneInfo

# Knowledge layout. Folders may nest at most 2 levels, so inbox folders are top-level.
BK_SETTINGS = "Bookkeeping/settings.json"
BK_CLIENTS = "Bookkeeping/Clients"
BK_RULES = "Bookkeeping/Rules"
BK_BILLS = "Bookkeeping/Bills"
BK_INBOX = "Bookkeeping Inbox"
BK_PROCESSED = "Bookkeeping Processed"
BK_FAILED = "Bookkeeping Failed"
BK_MAIL = "Bookkeeping/Mail"
BK_REQUESTS = "Bookkeeping Requests"


def bk_read_json(path, default=None):
    try:
        raw = api.files.read(file=path)
    except Exception:
        return default
    try:
        return json.loads(raw)
    except Exception:
        return default


def bk_write_json(path, data):
    api.files.put(file=path, content=json.dumps(data, indent=2, sort_keys=True))


def bk_money(value):
    """Parse 1234.5, "1,234.50", "$12" or "A$ 12.00" into a float; None when blank or not a number."""
    if value is None or isinstance(value, bool):
        return None
    if isinstance(value, (int, float)):
        return float(value)
    s = re.sub(r"[^0-9.\-]", "", str(value))
    if s in ("", "-", ".", "-."):
        return None
    try:
        return float(s)
    except ValueError:
        return None


def bk_fmt(amount, currency=""):
    if amount is None:
        return "—"
    return (currency + " " if currency else "") + "{:,.2f}".format(amount)


def bk_tz(settings):
    # The sandbox may lack the tz database; fall back to AEST (UTC+10) rather than failing the run.
    try:
        return ZoneInfo((settings or {}).get("timezone") or "Australia/Sydney")
    except Exception:
        return datetime.timezone(datetime.timedelta(hours=10))


def bk_today(settings):
    return datetime.datetime.now(bk_tz(settings)).date()


def bk_now_iso(settings):
    return datetime.datetime.now(bk_tz(settings)).replace(microsecond=0).isoformat()


def bk_add_business_days(day, n):
    d = day
    while n > 0:
        d = d + datetime.timedelta(days=1)
        if d.weekday() < 5:
            n -= 1
    return d


def bk_norm(name):
    s = re.sub(r"[^a-z0-9 ]+", " ", str(name or "").lower())
    s = re.sub(r"\b(pty|ltd|limited|p/l|the|inc|co)\b", " ", s)
    return re.sub(r"\s+", " ", s).strip()


def bk_move(src, dst):
    """Move a knowledge file (binary-safe): copy through the run's scratch space, then delete the source."""
    local = api.files.get(file=src)
    with open(local, "rb") as fh:
        data = fh.read()
    scratch = api.files.scratch_path(dst.split("/")[-1])
    with open(scratch, "wb") as fh:
        fh.write(data)
    api.files.put(file=dst, scratch_file=scratch)
    api.files.delete(file=src)
    return dst


def bk_reviewer(settings, client):
    return (client or {}).get("reviewer_id") or (settings or {}).get("reviewer_id")


def bk_exceptions_owner(settings, client):
    return (settings or {}).get("exceptions_owner_id") or bk_reviewer(settings, client)


# ── bookkeeping kit: Xero ledger adapter (inlined into Xero nodes by gen-ext.js) ──
# Every write passes xero_tenant_id so it lands in the client's own Xero organisation
# (myhub-mcp-servers PR #558). Reads pass it too.
import base64
from collections import Counter

XERO = "xero-accounting"
XERO_EXPENSE_TYPES = {"EXPENSE", "DIRECTCOSTS", "OVERHEADS", "FIXED", "CURRENT", "INVENTORY", "PREPAYMENT", "NONCURRENT"}
XERO_REVENUE_TYPES = {"REVENUE", "SALES", "OTHERINCOME"}
XERO_DEAD = {"DELETED", "VOIDED"}


def xero_call(tool, tenant_id=None, **args):
    if tenant_id:
        args["xero_tenant_id"] = tenant_id
    # Bound first on purpose: the platform's Publish lint only counts plain assignments as a function's own names,
    # so an `except ... as exc` name alone reads as undefined inside a helper.
    exc = None
    try:
        return api.connectors.invoke(server=XERO, tool=tool, args=args)
    except Exception as exc:
        raise RuntimeError(xero_error_text(exc)) from None


def xero_error_text(exc):
    """Xero's own validation messages (the useful part, at the end of a long error), else the error text."""
    text = str(exc)
    at = text.find("ValidationErrors")
    messages = []
    for m in re.findall(r'"Message"\s*:\s*"((?:[^"\\]|\\.)*)"', text[at:] if at >= 0 else ""):
        if m not in messages:
            messages.append(m)
    return ("Xero says: " + "; ".join(messages)) if messages else text[:600]


def xero_q(value):
    return str(value).replace("\\", "\\\\").replace('"', '\\"')


def xero_rows(result, key):
    if isinstance(result, dict):
        return result.get(key) or []
    if isinstance(result, list):
        return result
    return []


def xero_find_supplier(tenant_id, name, abn):
    """Existing contact by ABN (TaxNumber) first, then by normalised name. None when not found."""
    if not name:
        return None
    rows = xero_rows(xero_call("list_contacts", tenant_id, searchTerm=str(name)[:60]), "Contacts")
    abn_digits = "".join(ch for ch in str(abn or "") if ch.isdigit())
    if abn_digits:
        for c in rows:
            if "".join(ch for ch in str(c.get("TaxNumber") or "") if ch.isdigit()) == abn_digits:
                return c
    target = bk_norm(name)
    for c in rows:
        if bk_norm(c.get("Name")) == target:
            return c
    return None


def xero_attach_file(tenant_id, host_type, host_id, knowledge_path, file_name):
    """Attach a Knowledge PDF to a Xero record (Invoices, Accounts, Contacts, ...). Returns '' or the error text."""
    exc = None  # see xero_call
    try:
        local = api.files.get(file=knowledge_path)
        with open(local, "rb") as fh:
            content = base64.b64encode(fh.read()).decode("ascii")
        xero_call("upload_attachment", tenant_id, hostType=host_type, hostId=host_id,
                  fileName=file_name, base64Content=content, mimeType="application/pdf")
        return ""
    except Exception as exc:
        return str(exc)[:300]


def xero_match_bank(accounts, statement):
    """The Xero bank account a bank or card statement belongs to: by account or card number, then by name. None when
    no account or more than one fits."""
    digits = "".join(ch for ch in str(statement.get("bsb") or "") + str(statement.get("account_number") or "") if ch.isdigit())
    number = "".join(ch for ch in str(statement.get("account_number") or "") if ch.isdigit())
    card = "".join(ch for ch in str(statement.get("card_last4") or "") if ch.isdigit())[-4:]
    hits = []
    for a in accounts:
        theirs = "".join(ch for ch in str(a.get("BankAccountNumber") or "") if ch.isdigit())
        if not theirs:
            continue
        # Statements often print only part of the number, so the last four digits decide (two hits = unsure).
        if ((len(number) >= 4 and len(theirs) >= 4 and theirs[-4:] == number[-4:]) or (digits and digits == theirs)
                or (len(card) == 4 and theirs.endswith(card))):
            hits.append(a)
    if len(hits) == 1:
        return hits[0]
    if hits:
        return None
    names = [bk_norm(statement.get(k)) for k in ("account_name", "institution") if bk_norm(statement.get(k))]
    by_name = [a for a in accounts if any(n and (n in bk_norm(a.get("Name")) or bk_norm(a.get("Name")) in n) for n in names)]
    return by_name[0] if len(by_name) == 1 else None


def xero_open_balance(tenant_id, contact_id, doc_type):
    """What's still owing on the contact's approved bills (ACCPAY) or invoices (ACCREC), and their invoice numbers."""
    owing, numbers = 0.0, set()
    for status_name in ("SUBMITTED", "AUTHORISED"):
        where = 'Type=="%s" AND Status=="%s" AND Contact.ContactID==guid("%s")' % (doc_type, status_name, xero_q(contact_id))
        for inv in xero_rows(xero_call("list_invoices", tenant_id, where=where), "Invoices"):
            owing += bk_money(inv.get("AmountDue")) or 0
    where = 'Type=="%s" AND Contact.ContactID==guid("%s")' % (doc_type, xero_q(contact_id))
    for inv in xero_rows(xero_call("list_invoices", tenant_id, where=where), "Invoices"):
        if inv.get("Status") not in XERO_DEAD and inv.get("InvoiceNumber"):
            numbers.add(bk_norm(inv["InvoiceNumber"]))
    return round(owing, 2), numbers


# ── File the statement in Xero ──


BK_STATEMENTS = "Bookkeeping/Statements"  # one log per client of every statement filed
XERO_CSV_HEADER = "*Date,*Amount,Payee,Description,Reference,Check Number"  # Xero's bank statement CSV template


def bank_summary(tenant_id, account, start, end):
    """The account's opening and closing balance in Xero over the period (Bank Summary report): (opening, closing),
    either None when Xero doesn't say."""
    report = xero_call("get_bank_summary", tenant_id, fromDate=str(start or end), toDate=str(end))
    reports = report.get("Reports") if isinstance(report, dict) else None
    rows = (reports[0] if reports else (report if isinstance(report, dict) else {})).get("Rows") or []
    stack = list(rows)
    while stack:
        row = stack.pop(0)
        stack.extend(row.get("Rows") or [])
        cells = row.get("Cells") or []
        if len(cells) < 2:
            continue
        ids = [att.get("Value") for c in cells for att in (c.get("Attributes") or []) if isinstance(att, dict)]
        if account.get("AccountID") in ids or bk_norm(cells[0].get("Value")) == bk_norm(account.get("Name")):
            return bk_money(cells[1].get("Value")), bk_money(cells[-1].get("Value"))
    return None, None


def csv_cell(value):
    text = re.sub(r"\s+", " ", str(value if value is not None else "")).strip()
    return '"' + text.replace('"', '""') + '"' if ("," in text or '"' in text) else text


def statement_lines(rows):
    """The statement's transactions as [(date, amount, description, reference)], or None if any line is unreadable."""
    out = []
    for r in rows or []:
        when = str(r.get("date") or "")
        amount = bk_money(r.get("amount"))
        if not re.match(r"^\d{4}-\d{2}-\d{2}$", when) or amount is None:
            return None
        out.append((when, round(amount, 2), str(r.get("description") or "").strip(), str(r.get("reference") or "").strip()))
    return out

ctx = params.get("ctx") or {}
st = params.get("statement") or {}
path = params["path"]
settings = ctx.get("settings") or {}
client = ctx.get("client") or {}
slug = client.get("slug") or ctx.get("folder") or path.split("/")[1]
tenant = client.get("xero_tenant_id")
today = bk_today(settings)
kind = str(st.get("kind") or "").lower()
period = (str(st.get("period_start") or "") + " to " if st.get("period_start") else "") + str(st.get("period_end") or "")
closing = bk_money(st.get("closing_balance"))
problem = ""
issues = []
filed_to = ""
label = ""
outcome = ""
todo_id = ""
csv_path = ""
import_rows = []
import_notes = []

try:
    host_type, host_id = "", ""
    if kind in ("bank", "credit card", "credit_card", "card"):
        accounts = xero_rows(xero_call("list_accounts", tenant, where='Type=="BANK"'), "Accounts")
        acct = xero_match_bank(accounts, st)
        if not acct:
            problem = ("Couldn't tell which bank account in Xero this statement is for (" + " ".join(
                str(st.get(k)) for k in ("institution", "account_name", "account_number", "card_last4") if st.get(k))
                + "). Bank accounts in Xero: " + (", ".join(str(a.get("Name")) + " (" + str(a.get("BankAccountNumber") or "no number") + ")"
                                                         for a in accounts) or "none") + ".")
        else:
            host_type, host_id, label = "Accounts", acct["AccountID"], str(acct.get("Name"))
            filed_to = "bank account **" + label + "**"
            # Xero keeps a card balance owing as a negative number; the statement prints it as a positive one.
            sign = -1 if str(acct.get("BankAccountType") or "").upper() == "CREDITCARD" or kind != "bank" else 1
            opening = bk_money(st.get("opening_balance"))
            st_open = opening * sign if opening is not None else None
            st_close = closing * sign if closing is not None else None
            x_open, x_close = (bank_summary(tenant, acct, st.get("period_start"), st.get("period_end"))
                               if st.get("period_end") else (None, None))
            if x_close is None or st_close is None or abs(x_close - st_close) > 0.01:
                # Not in Xero yet (no bank feed, or not imported): turn the statement into a CSV for Xero's import.
                lines = statement_lines(st.get("lines"))
                moved = round(sum(t[1] for t in lines), 2) if lines else 0.0
                if lines and st_open is not None and st_close is not None and abs(st_open + moved - st_close) <= 0.01:
                    import_rows = lines
                    done = [e for e in (bk_read_json(BK_STATEMENTS + "/" + slug + ".json") or {}).get("statements") or []
                            if isinstance(e, dict) and e.get("import_file") and e.get("period") == period
                            and e.get("filed_to") == filed_to.replace("**", "")]
                    if done:
                        import_notes.append("**This statement already became an import file on " + str(done[-1].get("at"))[:10]
                                            + "** (`" + str(done[-1]["import_file"]) + "`). If that one was imported, don't "
                                            "import this one: just complete this item.")
